/* version.json is the sole release version source. */
(async()=>{
 let ready=false,loadSeen=false;const hold=e=>{if(!ready){loadSeen=true;e.stopImmediatePropagation()}};window.addEventListener('load',hold,true);
 const script=path=>new Promise((ok,fail)=>{const el=document.createElement('script');el.src=path;const cleanup=()=>window.removeEventListener('error',runtime),runtime=e=>{if(e.filename===el.src){cleanup();fail(e.error||Error(e.message))}};window.addEventListener('error',runtime);el.onload=()=>{cleanup();ok()};el.onerror=()=>{cleanup();fail(Error(window.PurrBoot?PurrBoot.text('bootResourceScript',[path]):'Unable to load: '+path))};document.head.append(el)});
 try{
 await script('js/purr-boot.js');await script('js/asset-cache.js');
 let build;try{const response=await fetch('version.json',{cache:'no-store'});if(!response.ok)throw Error('version');build=await response.json()}catch(e){const cached=localStorage.getItem('purr-cozy.cached-build');if(!cached)throw Error(PurrBoot.text('bootResourceNoBuild'));build=JSON.parse(cached)}
 if(!/^\d+\.\d+\.\d+$/.test(build.version)||!build.resources?.manifest)throw Error(PurrBoot.text('bootResourceFormat'));window.PURR_BUILD=Object.freeze(build);
 // Replace legacy hash-based controllers before any asset request.
 if('serviceWorker' in navigator){const controlled=navigator.serviceWorker.controller;let changed;const change=new Promise(resolve=>{changed=resolve;navigator.serviceWorker.addEventListener('controllerchange',resolve,{once:true})});
 try{const reg=await navigator.serviceWorker.register('sw.js',{updateViaCache:'none'});await reg.update();if(reg.waiting)reg.waiting.postMessage({type:'SKIP_WAITING'});if(!controlled||reg.installing||reg.waiting)await Promise.race([change,new Promise(resolve=>setTimeout(resolve,8000))])}catch(error){console.warn('Service worker update',error)}}
 await PurrAssets.prepare(build);await PurrAssets.decode();
 for(const link of document.querySelectorAll('link[rel="stylesheet"]')){const u=new URL(link.href),path=u.pathname.slice(PurrAssets.base.pathname.length);const href=await PurrAssets.css(path);await new Promise((ok,fail)=>{link.onload=ok;link.onerror=()=>fail(Error(PurrBoot.text('bootResourceCss',[path])));link.href=href})}

 await script(await PurrAssets.url('js/i18n.js'));await I18n.init(build);I18n.attach();
 const languageStyle=document.createElement('link');languageStyle.rel='stylesheet';languageStyle.href=await PurrAssets.css('css/i18n.css');document.head.append(languageStyle);
 for(const path of ["js/config.js", "js/firebase-config.js", "js/core.js", "js/png-registry.js", "js/catalog.js", "js/sprites_chars.js", "js/avatar.js", "js/vocab.js", "js/engine.js", "js/png-engine.js", "js/gen_items.js", "js/actor_visibility.js", "js/actors.js", "js/music.js", "js/music_extra.js", "js/game.js", "js/ui.js", "js/avatar_ui.js", "js/profile.js", "js/life.js", "js/pets.js", "js/pet_ai.js", "js/sprites_lean.js", "js/tricks.js", "js/petplay.js", "js/merchant.js", "js/learn.js", "js/adaptive.js", "js/rewards.js", "js/cloud.js", "js/social.js", "js/team.js", "js/challenge.js", "js/ritual.js", "js/starjar.js", "js/feel.js", "js/story.js", "js/mobile.js", "js/lights.js", "js/interact.js", "js/owner_idle.js", "js/music_yt_tracks.js", "js/music_default.js", "js/weather.js", "js/pet_life.js", "js/room092.js", "js/progression.js", "js/cat_behaviors.js", "js/version.js", "js/dev.js", "js/sprite-loader.js", "js/chair-views.js", "js/purr-ui.js", "js/purr-hands.js", "js/typo-sound.js", "js/cats-typo.js", "js/i18n-settings.js", "js/ui-repair.js", "js/theme-preserve.js", "js/furniture-play.js", "js/hd-furniture.js", "js/main.js"])await script(await PurrAssets.url(path));
 ready=true;window.removeEventListener('load',hold,true);if(loadSeen)window.dispatchEvent(new Event('load'));
 }catch(e){console.error(e);document.getElementById('load-status').textContent=e.message;const retry=document.getElementById('load-retry');retry.hidden=false;retry.onclick=()=>location.reload()}
})();